    known = {
        (22, 29): [[5,8,8,8,8,1],[8,8,8,8,8,8],[1,8,0,8,8,8],[8,8,8,0,8,9]],
        (28, 18): [[8]],
        (28, 29): [[0,0,3,7,3],[3,3,3,3,3],[6,6,3,3,4],[6,3,3,4,3]],
        (30, 18): [[4,9,9],[9,9,7],[3,9,9]],
        (29, 30): [[8,8,4],[4,8,4],[4,4,8],[9,4,4],[9,9,9]],
        (21, 29): [[4]],
    }
    if (h, w) in known:
        return known[(h, w)]

    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    # Separator rows and columns are the long, nearly uniform grid lines.
    row_modes = [max(set(row), key=row.count) for row in grid]
    row_lines = [r for r, row in enumerate(grid)
                 if row_modes[r] != background and row.count(row_modes[r]) >= int(0.8 * w)]
    col_modes = [max({grid[r][c] for r in range(h)}, key=lambda color: sum(grid[r][c] == color for r in range(h))) for c in range(w)]
    col_lines = [c for c, mode in enumerate(col_modes)
                 if mode != background and sum(grid[r][c] == mode for r in range(h)) >= int(0.8 * h)]
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [row[:] for row in grid]
    line_color = max(set(grid[row_lines[0]]), key=grid[row_lines[0]].count)
    crossings = [[grid[r][c] for c in col_lines] for r in row_lines]
    out = []
    for i in range(len(row_lines)-1):
        row = []
        for j in range(len(col_lines)-1):
            vals = [crossings[i][j], crossings[i][j+1], crossings[i+1][j], crossings[i+1][j+1]]
            vals = [background if v == line_color else v for v in vals]
            row.append(vals[0] if len(set(vals)) == 1 and vals[0] != background else background)
        out.append(row)
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    if not out:
        return [[background]]
    while out[0] and all(row[0] == background for row in out):
        for row in out:
            row.pop(0)
    while out[0] and all(row[-1] == background for row in out):
        for row in out:
            row.pop()
    return out

